L(OA24, 1,
  MAT_I,
  "Aprenderé a delimitar un tema de investigación sobre lenguaje y literatura y a formular una pregunta clara que se pueda responder con fuentes.",
  ["Conozco los géneros literarios.", "Sé acotar el tema de una exposición."],
  ["Una investigación parte de una duda. Para que sea posible, hay que delimitar el tema: pasar de un asunto amplio a uno acotado. «La poesía» es amplio; «Las metáforas en la poesía» está más acotado. Luego se convierte en una pregunta de investigación: «¿Cómo usan las metáforas los poemas para describir la naturaleza?».",
   "Una buena pregunta de investigación cumple cuatro condiciones. Es clara (se entiende sin explicarla), acotada (cabe en el tiempo disponible), abierta (no se responde con sí o no) y respondible con fuentes (hay textos donde buscar). «¿Hay metáforas en los poemas?» es cerrada y demasiado fácil. «¿Qué es la mejor poesía?» no se puede responder con fuentes porque depende del gusto.",
   "También conviene que la pregunta sirva a un propósito: complementar una lectura o resolver una duda sobre el lenguaje o la literatura. Por ejemplo, después de leer un cuento, podrías preguntar: «¿Qué tipos de narrador existen y cuál usa mi cuento?». Anota tu tema, tu pregunta y para qué la necesitas. Si la pregunta es muy grande, divídela en dos más pequeñas."],
  [("investigación", "búsqueda ordenada de información para responder una pregunta"), ("delimitar", "reducir un tema para poder tratarlo"), ("pregunta de investigación", "pregunta abierta, clara y respondible con fuentes"), ("fuente", "texto o persona de donde se obtiene información")],
  [("Acotar un tema", "¿Qué tema está más acotado: «La literatura» o «El narrador en los cuentos»?",
    ["El primero abarca todo.", "El segundo elige un aspecto.", "Está más acotado el segundo."],
    "El narrador en los cuentos"),
   ("Revisar una pregunta", "¿Qué defecto tiene «¿Hay narradores en los cuentos?»?",
    ["Se responde con sí o no.", "No obliga a investigar.", "Es una pregunta cerrada."],
    "Es cerrada")],
  [("Elegir un tema tan amplio que nunca se termina.", "Se piensa que mientras más, mejor.", "Acota hasta un aspecto manejable."),
   ("Formular una pregunta de sí o no.", "Se responde sin investigar.", "Pregunta «cómo», «por qué» o «qué tipos».")],
  ([E("¿Qué tema está más acotado: «La poesía» o «Las metáforas en la poesía»?", "Las metáforas en la poesía", "Elige un aspecto concreto."),
    E("¿«¿Hay metáforas en los poemas?» es abierta o cerrada?", "Cerrada", "Se responde con sí o no."),
    E("¿Para qué sirve delimitar un tema?", "Para poder tratarlo en el tiempo disponible", "Un tema muy amplio no se alcanza a investigar.")],
   [E("¿Qué pregunta es abierta: «¿Cómo usan las metáforas los poemas para describir la naturaleza?» o «¿Hay poemas con metáforas?»", "¿Cómo usan las metáforas los poemas para describir la naturaleza?", "Pide una explicación."),
    E("¿«¿Cuál es el mejor poema?» se puede responder con fuentes?", "No", "Depende del gusto personal."),
    E("¿Qué condición incumple «¿Hay metáforas?»: ser abierta o ser clara?", "Ser abierta", "Se responde con sí o no.")],
   [E("Entre «¿Qué tipos de narrador existen?», «¿Quién fue el mejor narrador?» y «¿Hay narrador?», ¿cuál se responde mejor con fuentes?", "¿Qué tipos de narrador existen?", "Es abierta y se puede buscar."),
    E("Tu pregunta es demasiado grande para 4 clases. ¿Qué haces: dividirla en dos o ampliarla?", "Dividirla en dos", "Así se acota."),
    E("Después de leer un cuento duda sobre qué narrador usa. ¿Cuál es el propósito de investigar: complementar la lectura o pasar el rato?", "Complementar la lectura", "La duda surge del cuento.")],
   [E("Ana escribe «La literatura» como tema. Beto escribe «El narrador en las leyendas». ¿Quién delimitó mejor?", "Beto", "Eligió un aspecto y un género."),
    E("Un compañero dice: «Mi pregunta es: ¿qué es lo más bonito del lenguaje?». ¿Es respondible con fuentes?", "No", "Es una valoración personal.")],
   [E("El tema «Los cuentos» es amplio. ¿Qué haces primero para convertirlo en pregunta: delimitarlo o empezar a copiar textos?", "Delimitarlo", "Primero se reduce el tema."),
    E("Tres preguntas: «¿Qué es un haiku?», «¿Existen los haikus?» y «¿Cómo se organiza un haiku?». ¿Cuántas son cerradas?", "1", "Solo «¿Existen los haikus?» se responde con sí o no.")]),
  [E("Leíste un cuento donde la narradora cuenta lo que le pasó a ella. Te interesa saber más sobre el narrador. ¿Cuál es una buena pregunta de investigación: «¿Qué tipos de narrador existen y cuál usa mi cuento?» o «¿Es bueno el cuento?»", "¿Qué tipos de narrador existen y cuál usa mi cuento?", "Se puede responder con fuentes.")],
  [E("¿Qué debe ser una pregunta de investigación respecto del sí o no?", "Abierta", "No se responde con sí o no."),
   E("¿Qué significa delimitar?", "Reducir un tema para poder tratarlo", "Lo hace manejable."),
   E("¿Una pregunta sobre gustos personales se responde con fuentes?", "No", "Depende de cada persona.")],
  ("Elige uno de estos temas amplios: «La poesía», «El cuento», «Las palabras». 1) Escribe un tema acotado. 2) Escribe una pregunta de investigación que sea clara, acotada, abierta y respondible con fuentes. 3) Explica en una frase para qué la necesitas.",
   "Tema amplio: el cuento. Acotado: el narrador en los cuentos. Pregunta: ¿Qué tipos de narrador existen y cómo cambia lo que sabemos de la historia? Para qué: entender mejor un cuento que leímos en clase.",
   ["acota el tema", "formula pregunta abierta y respondible", "explica el propósito"], ["tema", "pregunta", "propósito"], ["pregunta de sí o no", "tema aún amplio"], "Léela a otra persona y pregunta si sabe dónde buscaría la respuesta."),
  "Anota tres dudas que tengas sobre una lectura y conviértelas en preguntas de investigación.",
  "Reescribe tres preguntas cerradas como abiertas.")

L(OA24, 2,
  MAT_I,
  "Aprenderé a diseñar palabras clave y rutas de búsqueda en la biblioteca y en internet para encontrar fuentes útiles.",
  ["Formulo preguntas de investigación.", "Sé qué es un título y un autor."],
  ["Las palabras clave son los términos esenciales de tu pregunta. Para «¿Qué tipos de narrador existen?» son «narrador» y «tipos». Se obtienen eliminando palabras de relleno («qué», «de») y manteniendo las que nombran el tema. A veces conviene agregar sinónimos o términos relacionados: «narrador», «voz narrativa», «punto de vista».",
   "Hay varias rutas de búsqueda. En la biblioteca puedes usar el catálogo, que permite buscar por autor, título o materia (el tema del libro), o consultar a la bibliotecaria. En internet usa un buscador y combina las palabras clave. Si escribes una frase entre comillas, el buscador busca esas palabras juntas y en ese orden: «tipos de narrador».",
   "Ajusta la búsqueda según el resultado. Si hay demasiados resultados poco relacionados, agrega una palabra más específica. Si hay muy pocos, usa un sinónimo o quita una palabra. Anota qué combinaciones probaste y cuáles te sirvieron: así no repites el trabajo. Una búsqueda ordenada ahorra tiempo y mejora los resultados."],
  [("palabra clave", "término esencial para buscar información"), ("catálogo", "lista de los libros de una biblioteca que se puede buscar por autor, título o materia"), ("materia", "tema principal de un libro en un catálogo"), ("frase exacta", "búsqueda entre comillas que pide las palabras juntas y en orden")],
  [("Extraer palabras clave", "Pregunta: «¿Cómo usan las metáforas los poemas para describir la naturaleza?». ¿Cuáles son las palabras clave?",
    ["Quito las palabras de relleno.", "Quedan «metáforas», «poemas» y «naturaleza».", "Esas son las palabras clave."],
    "metáforas, poemas, naturaleza"),
   ("Ajustar la búsqueda", "Tu búsqueda «poesía» da miles de resultados. ¿Qué haces?",
    ["Es demasiado amplia.", "Agrego una palabra específica.", "Escribo «metáforas en la poesía»."],
    "Agrego una palabra específica, como «metáforas en la poesía»")],
  [("Escribir la pregunta completa en el buscador.", "Se piensa que así se encuentra más.", "Usa las palabras clave."),
   ("Quedarse con la primera búsqueda.", "No se ajusta aunque no funcione.", "Cambia, agrega o quita palabras.")],
  ([E("En «¿Qué tipos de narrador existen?», ¿«narrador» es palabra clave o de relleno?", "Palabra clave", "Nombra el tema."),
    E("¿Qué se usa en la biblioteca para buscar por autor, título o materia: el catálogo o el mostrador?", "El catálogo", "Permite buscar por esos datos."),
    E("¿Qué hace escribir una frase entre comillas en un buscador: busca las palabras juntas o por separado?", "Juntas y en orden", "Es la frase exacta.")],
   [E("Pregunta: «¿Qué recursos usan los cuentos para crear suspenso?». ¿Cuál no es palabra clave: «cuentos» o «qué»?", "qué", "Es una palabra de relleno para buscar."),
    E("Quieres libros sobre cuentos. ¿Qué campo del catálogo usas: autor o materia?", "Materia", "No conoces al autor."),
    E("Si hay demasiados resultados, ¿agregas una palabra específica o quitas todas?", "Agregas una palabra específica", "Acota la búsqueda.")],
   [E("Catálogo de ejemplo: 1) «Guía del cuento»; materia: cuento. 2) «Poemas del mar»; materia: poesía. 3) «Historia del teatro»; materia: teatro. Buscas un libro sobre cuentos. ¿Cuál pides?", "Guía del cuento", "Su materia es cuento."),
    arith("Quieres buscar con 2 sinónimos de «narrador» y 3 sinónimos de «tipos». ¿Cuántas combinaciones de dos palabras puedes probar?", "2*3", "Se multiplica cada sinónimo del primero por los del segundo."),
    E("¿Cuál es mejor búsqueda: «tipos de narrador» entre comillas o «qué tipos de narrador existen y cuál usa el cuento que leí ayer»?", "«tipos de narrador» entre comillas", "Usa palabras clave en frase exacta.")],
   [E("Ana escribe toda su pregunta en el buscador. Beto escribe «metáforas poesía naturaleza». ¿Quién usó palabras clave?", "Beto", "Eliminó el relleno."),
    E("Una búsqueda da solo 2 resultados. ¿Qué conviene: usar un sinónimo o agregar más palabras?", "Usar un sinónimo", "Amplía la búsqueda.")],
   [E("Catálogo de ejemplo: 1) «Guía del cuento»; materia: cuento. 2) «Poemas del mar»; materia: poesía. 3) «Historia del teatro»; materia: teatro. ¿Cuántos libros aparecen si buscas por las materias poesía y teatro?", "2", "«Poemas del mar» y «Historia del teatro»."),
    E("Haces tres búsquedas distintas y solo una te sirve. ¿Qué anotas: la que sirvió o todas?", "Todas con su resultado", "Así no repites las que no sirven.")]),
  [E("Tu pregunta es «¿Qué es un narrador omnisciente?». Estas son tus palabras clave posibles: «narrador omnisciente» y «qué es». ¿Cuál usarías en el buscador?", "narrador omnisciente", "Nombra el tema.")],
  [E("En Lenguaje: ¿Qué es una palabra clave?", "Un término esencial para buscar", "Sale de la pregunta."),
   E("¿Qué es la materia en un catálogo?", "El tema principal del libro", "Se usa para buscar por tema."),
   E("¿Cuándo usas un sinónimo en la búsqueda?", "Cuando hay pocos resultados", "Amplía las posibilidades.")],
  ("Para la pregunta «¿Qué diferencias hay entre un cuento y una leyenda?» escribe: 1) las palabras clave; 2) un sinónimo para una de ellas; 3) una búsqueda con comillas; 4) qué harías si salen demasiados resultados.",
   "Palabras clave: cuento, leyenda, diferencias. Sinónimo: relato. Búsqueda: «diferencias entre cuento y leyenda». Si hay demasiados, agrego «narración» o «características».",
   ["extrae palabras clave", "propone un sinónimo", "usa comillas", "ajusta la búsqueda"], ["cuatro respuestas"], ["usar toda la pregunta", "no ajustar"], "Prueba la búsqueda con alguien que te diga si los resultados parecen útiles."),
  "Si tienes un libro en casa, busca su materia en la contraportada o el índice.",
  "Escribe diez palabras clave para tres preguntas sobre lenguaje.")

L(OA24, 3,
  MAT_I,
  "Aprenderé a localizar información en un texto usando sus organizadores: índice, títulos, subtítulos, negritas, glosario, introducción y conclusión.",
  ["Diseño palabras clave.", "Sé qué es un capítulo."],
  ["Los textos informativos traen organizadores que ayudan a ubicar información sin leer todo. El índice o tabla de contenidos enumera los capítulos con su página. Los títulos y subtítulos anuncian el tema de cada parte. Las negritas destacan conceptos importantes. El glosario explica palabras difíciles. La introducción presenta el tema y la conclusión resume lo central.",
   "Para buscar de manera eficiente, sigue estos pasos: 1) busca tus palabras clave en el índice; 2) ve a la página indicada; 3) recorre títulos y subtítulos; 4) lee solo el apartado que corresponde; 5) revisa las negritas para confirmar. Si no está en el índice, prueba con el índice analítico (al final del libro) o con la introducción.",
   "En una página web los organizadores son los menús, los encabezados y el buscador interno. Aplica la misma lógica: lee primero el título y los subtítulos antes de decidir si el sitio sirve. Un texto bien organizado ahorra tiempo, y si el texto no tiene organizadores, escanéalo en busca de tus palabras clave."],
  [("índice", "lista de capítulos con sus páginas al comienzo o final de un libro"), ("subtítulo", "título de una subparte dentro de un capítulo"), ("glosario", "lista de palabras con su significado"), ("conclusión", "parte final que resume lo central")],
  [("Usar el índice", "Índice de ejemplo: Cap. 1 El cuento, p. 5–12; Cap. 2 El narrador, p. 13–22; Cap. 3 La leyenda, p. 23–30. Buscas el narrador. ¿En qué página empiezas?",
    ["Busco «narrador» en el índice.", "Está en el capítulo 2.", "Empieza en la página 13."],
    "Página 13"),
   ("Leer solo lo necesario", "Dentro del capítulo 2 hay subtítulos: «Narrador protagonista», «Narrador testigo», «Narrador omnisciente». Buscas el testigo. ¿Qué lees?",
    ["Reviso los subtítulos.", "Encuentro «Narrador testigo».", "Leo solo ese apartado."],
    "Solo el apartado «Narrador testigo»")],
  [("Leer todo el libro para encontrar un dato.", "No se usan los organizadores.", "Parte por el índice y los subtítulos."),
   ("Ignorar el glosario.", "Se salta lo que explica palabras difíciles.", "Consúltalo cuando una palabra no se entienda.")],
  ([E("Índice de ejemplo: Cap. 1 El cuento, p. 5–12; Cap. 2 El narrador, p. 13–22; Cap. 3 La leyenda, p. 23–30. ¿Qué capítulo empieza en la página 23?", "El capítulo 3, La leyenda", "Su rango parte en esa página."),
    E("¿Qué organizador explica palabras difíciles: el glosario o el índice?", "El glosario", "Define las palabras difíciles."),
    E("¿Qué organizador presenta el tema al comienzo: la introducción o la conclusión?", "La introducción", "Abre el texto.")],
   [E("Índice de ejemplo: Cap. 1 El cuento, p. 5–12; Cap. 2 El narrador, p. 13–22; Cap. 3 La leyenda, p. 23–30. ¿En qué capítulo buscas información sobre leyendas?", "Capítulo 3", "Tiene ese título."),
    arith("Del capítulo 3 de ese índice (p. 23–30), ¿cuántas páginas tiene, contando la 23 y la 30?", "30-23+1", "Se incluyen ambas páginas."),
    E("¿Para qué sirven las negritas?", "Para destacar conceptos importantes", "Ayudan a ubicar lo esencial.")],
   [arith("El capítulo 2 va de la página 13 a la 22. ¿Cuántas páginas tiene?", "22-13+1", "Se cuentan ambas páginas."),
    E("Buscas en qué páginas se habla del narrador «omnisciente» y esa palabra no está en el índice de capítulos. ¿Qué pruebas: el índice analítico o el glosario?", "El índice analítico", "Lista términos específicos con páginas."),
    E("En una web, ¿qué función cumplen los encabezados: anuncian el tema de cada parte o decoran?", "Anuncian el tema de cada parte", "Se comportan como subtítulos.")],
   [E("Ana lee todo el libro para hallar un dato. Beto va al índice y luego a los subtítulos. ¿Quién fue más eficiente?", "Beto", "Usó los organizadores."),
    E("Una página web tiene un menú con «Cuento», «Poesía» y «Teatro». Buscas poemas. ¿Qué opción eliges?", "Poesía", "Corresponde al género.")],
   [E("El glosario de un libro está en la página 118 y la introducción en la página 3. ¿Cuál consultas al final del libro?", "El glosario", "Está casi al final."),
    E("Buscas «el narrador» en una web con el menú «Inicio, Narración, Poesía, Contacto». ¿Qué opción eliges?", "Narración", "Es la sección que trata ese tema.")]),
  [E("Tu biblioteca tiene un libro sobre lenguaje. Su índice dice: «Los sinónimos, p. 40; Los antónimos, p. 45; Las palabras compuestas, p. 52». Buscas antónimos. ¿En qué página abres?", "45", "Es la página que indica el índice.")],
  [E("¿Qué muestra el índice?", "Los capítulos con su página", "Ordena el contenido."),
   E("¿Para qué sirve el glosario?", "Para explicar palabras difíciles", "Define las palabras difíciles."),
   E("¿Qué se lee primero en una página web: el título y los subtítulos o todo?", "El título y los subtítulos", "Ayudan a decidir si sirve.")],
  ("Con este índice de ejemplo: «Introducción, p. 3; 1. Qué es un texto narrativo, p. 5; 2. Partes de una narración, p. 12; 3. Tipos de narrador, p. 20; 4. Los personajes, p. 30; Glosario, p. 38». Responde: 1) ¿en qué página buscas los tipos de narrador? 2) ¿cuántas páginas ocupa el capítulo 3? 3) ¿dónde buscarías el significado de «narratario»?",
   "1) Página 20. 2) El capítulo 3 va de la 20 a la 29: 10 páginas (20 a 29 incluye ambas). 3) En el glosario, página 38.",
   ["usa el índice", "calcula páginas", "usa el glosario"], ["tres respuestas"], ["leer todo el libro", "confundir páginas"], "Revisa con otra persona que ambas lleguen a la misma página."),
  "Elige un libro de tu casa y anota tres organizadores que tenga.",
  "Crea un índice de ejemplo de cinco capítulos para un libro sobre poesía.")

L(OA24, 4,
  MAT_I,
  "Aprenderé a evaluar si un texto es relevante y suficiente para responder mi pregunta de investigación.",
  ["Localizo información con organizadores.", "Distingo ideas principales."],
  ["No todo texto encontrado sirve. Para decidir, aplica dos criterios. La relevancia: ¿el texto trata directamente el tema de mi pregunta? La suficiencia: ¿entrega toda la información necesaria para responderla o solo una parte? Un texto puede ser relevante pero insuficiente, o suficiente pero poco relevante.",
   "Por ejemplo, para «¿Qué tipos de narrador existen?», un texto que define el narrador protagonista, el testigo y el omnisciente es relevante y suficiente. Un texto sobre la vida del autor es irrelevante para esa pregunta. Un texto que dice «hay varios tipos de narradores» sin explicarlos es relevante pero insuficiente.",
   "También conviene revisar la actualidad y la confiabilidad (clase de la exposición). Si no se cumple la suficiencia, busca otra fuente que complete lo que falta. Si ningún texto es suficiente, tu pregunta puede ser demasiado amplia y habrá que acotarla. Anota tu decisión: «Sirve», «Sirve en parte» o «No sirve», con el motivo."],
  [("relevancia", "relación directa de un texto con la pregunta"), ("suficiencia", "cantidad de información necesaria para responder la pregunta"), ("insuficiente", "que no entrega toda la información necesaria"), ("irrelevante", "que no se relaciona con la pregunta")],
  [("Aplicar los dos criterios", "Pregunta: «¿Qué tipos de narrador existen?». Texto: «El narrador protagonista cuenta en primera persona; el testigo observa y cuenta lo que ve; el omnisciente lo sabe todo». ¿Es relevante y suficiente?",
    ["Trata el tema directamente: relevante.", "Define tres tipos: suficiente.", "Sirve."],
    "Sí, es relevante y suficiente"),
   ("Texto insuficiente", "Texto: «Hay varios tipos de narradores». ¿Qué falla?",
    ["Es relevante.", "No explica cuáles son.", "Es insuficiente."],
    "Es relevante pero insuficiente")],
  [("Elegir un texto porque tiene la palabra clave.", "No se mira si responde la pregunta.", "Comprueba relevancia y suficiencia."),
   ("Usar un solo texto incompleto.", "Falta información.", "Busca otra fuente que complete.")],
  ([E("¿Qué mide la relevancia: si trata el tema de la pregunta o si tiene fotos?", "Si trata el tema de la pregunta", "Es la relación con la pregunta."),
    E("¿Qué mide la suficiencia: si entrega toda la información necesaria o si es corto?", "Si entrega toda la información necesaria", "Responde por completo."),
    E("Un texto sobre la vida de un autor, para la pregunta «¿Qué tipos de narrador existen?», ¿es relevante?", "No", "No trata los narradores.")],
   [E("Texto: «El narrador protagonista cuenta en primera persona; el testigo observa; el omnisciente lo sabe todo». Para «¿Qué tipos de narrador existen?», ¿es suficiente?", "Sí", "Nombra y explica los tipos."),
    E("Texto: «Hay muchos narradores». Para la misma pregunta, ¿es suficiente?", "No", "No explica cuáles son."),
    E("Un texto es relevante pero insuficiente. ¿Qué haces: buscas otra fuente o terminas?", "Buscas otra fuente", "Completa lo que falta.")],
   [E("Pregunta: «¿Cómo usan los poemas las metáforas?». Texto: «Una metáfora identifica una cosa con otra, como en “tus ojos son estrellas”». ¿Es relevante?", "Sí", "Explica y ejemplifica la metáfora."),
    E("Con ese mismo texto, ¿es suficiente para saber cómo la usan los poemas para describir la naturaleza?", "No", "Solo define y da un ejemplo."),
    E("Pregunta: «¿Qué es una leyenda?». Texto sobre la historia del libro impreso. ¿Es relevante?", "No", "No trata sobre leyendas.")],
   [E("Ana usa el primer texto que encuentra con la palabra «narrador». Beto lo compara con la pregunta antes de usarlo. ¿Quién aplicó los criterios?", "Beto", "Revisó relevancia y suficiencia."),
    E("Si ningún texto es suficiente, la pregunta puede ser demasiado amplia. ¿Qué haces: acotarla o ignorar el problema?", "Acotarla", "Hace posible responder.")],
   [E("Tienes 3 textos: dos relevantes y uno irrelevante. De los relevantes, uno es suficiente. ¿Cuántos sirven por completo?", "1", "Solo el relevante y suficiente."),
    E("¿Qué decisión anotas para un texto relevante pero incompleto: «Sirve», «Sirve en parte» o «No sirve»?", "Sirve en parte", "Aporta, pero falta información.")]),
  [E("Para responder «¿Qué diferencias hay entre cuento y leyenda?» encuentras un texto que solo describe qué es un cuento. ¿Es suficiente?", "No", "Falta la leyenda y la comparación.")],
  [E("¿Qué dos criterios se usan para decidir si un texto sirve?", "Relevancia y suficiencia", "Son los criterios de la clase."),
   E("¿Un texto puede ser relevante e insuficiente a la vez?", "Sí", "Trata el tema pero no lo agota."),
   E("¿Qué anotas al decidir sobre un texto?", "Sirve, sirve en parte o no sirve, con el motivo", "Registra tu criterio.")],
  ("Pregunta: «¿Qué es un narrador omnisciente?». Evalúa estos textos: A) «El narrador omnisciente conoce lo que piensan y sienten todos los personajes». B) «Hay varios tipos de narrador, entre ellos el omnisciente». C) «El autor del libro nació en un pueblo del sur». Para cada uno escribe si es relevante, si es suficiente y tu decisión.",
   "A: relevante y suficiente; sirve. B: relevante pero insuficiente, porque no dice qué es; sirve en parte. C: irrelevante; no sirve.",
   ["aplica dos criterios", "justifica con la pregunta", "toma una decisión"], ["tres evaluaciones"], ["decidir por la palabra clave", "no justificar"], "Comenta tu decisión con otra persona."),
  "Revisa un texto corto de un libro de casa y decide si responde una pregunta que te interese.",
  "Escribe tres textos breves: uno suficiente, uno insuficiente y uno irrelevante para la misma pregunta.")

L(OA24, 5,
  MAT_I,
  "Aprenderé a registrar la información encontrada en fichas, a distinguir cita textual y paráfrasis y a organizar las fichas en categorías.",
  ["Evalúo relevancia y suficiencia.", "Resumo con palabras propias."],
  ["Registrar significa anotar la información importante para no olvidarla. Una ficha de registro tiene cuatro partes: los datos de la fuente (autor, título, año), la información (cita textual o paráfrasis), la categoría (a qué subtema pertenece) y la página. Una cita textual reproduce las palabras exactas y va entre comillas: «El narrador testigo cuenta lo que observa». Una paráfrasis dice lo mismo con palabras propias.",
   "Las categorías son los grupos en que ordenas tus fichas. Si investigas «¿Qué tipos de narrador existen?», tus categorías pueden ser «protagonista», «testigo» y «omnisciente». Ordenar por categorías permite ver qué información tienes y qué te falta. Una ficha va a una sola categoría, la que mejor corresponde.",
   "Copiar sin comillas ni fuente es plagio. Para evitarlo, anota siempre la fuente y distingue cita de paráfrasis. Cuando parafrasees, cambia las palabras y la estructura, pero conserva el sentido. Una ficha bien hecha permite escribir tu informe sin volver a leer los textos completos."],
  [("ficha de registro", "tarjeta con los datos de una fuente y la información que se extrajo"), ("cita textual", "texto copiado tal cual, entre comillas, con su fuente"), ("paráfrasis", "idea expresada con palabras propias"), ("categoría", "grupo en que se ordena la información")],
  [("Clasificar una ficha", "Ficha de ejemplo: «El narrador testigo cuenta lo que ve sin saber lo que piensan los demás». ¿A qué categoría de «tipos de narrador» pertenece?",
    ["Veo la palabra clave: testigo.", "La ficha explica ese tipo.", "Va a la categoría «testigo»."],
    "Testigo"),
   ("Distinguir cita y paráfrasis", "«El narrador omnisciente lo sabe todo» (con comillas, tal cual en el libro) y «El que cuenta conoce todo lo que piensan los personajes» (con palabras propias). ¿Cuál es la cita?",
    ["La cita copia exacto.", "La primera tiene comillas y palabras exactas.", "La segunda es paráfrasis."],
    "La primera")],
  [("Copiar sin comillas ni fuente.", "Se piensa que da igual.", "Usa comillas y anota la fuente: si no, es plagio."),
   ("Cambiar una palabra y creer que parafraseaste.", "Se mantiene la estructura.", "Reescribe con tus palabras conservando el sentido.")],
  ([E("¿Una cita textual lleva comillas?", "Sí", "Indica palabras exactas de otro."),
    E("¿La paráfrasis usa palabras propias o exactas?", "Propias", "Conserva el sentido."),
    E("¿Una ficha de registro anota los datos de la fuente?", "Sí", "Los datos permiten comprobar la fuente.")],
   [E("Ficha: «El narrador protagonista cuenta en primera persona». ¿A qué categoría pertenece: protagonista o testigo?", "Protagonista", "Cuenta lo vivido por él."),
    E("Ficha: «El narrador omnisciente conoce lo que sienten todos». ¿Va en la categoría omnisciente?", "Sí", "Habla de ese tipo."),
    E("Copias dos líneas de un libro sin comillas ni fuente. ¿Es plagio?", "Sí", "No indicas que no son tuyas.")],
   [E("Tienes 5 fichas: 2 de protagonista, 1 de testigo y 2 de omnisciente. ¿En qué categoría hay menos fichas?", "Testigo", "Solo tiene una."),
    arith("Tienes 12 fichas: 5 de protagonista, 4 de testigo y las demás de omnisciente. ¿Cuántas son de omnisciente?", "12-5-4", "Se restan las de las otras dos categorías."),
    E("¿Cuántas partes tiene una ficha de registro según la clase?", "4", "Son fuente, información, categoría y página.")],
   [E("Ana copia: «El narrador testigo observa y cuenta». Beto escribe: «El que cuenta desde fuera solo describe lo que ve». ¿Quién parafraseó?", "Beto", "Usó palabras propias."),
    E("Una ficha puede pertenecer a dos categorías a la vez según la clase. ¿Es correcto?", "No", "Va a la que mejor corresponde.")],
   [E("Si te faltan fichas para una categoría, ¿qué hace falta: buscar más información o borrar la categoría?", "Buscar más información", "Completa lo que falta."),
    E("En la ficha «Guzmán, Ana. Guía del narrador. 2020. p. 18», ¿qué parte es la página?", "p. 18", "Indica dónde está la información.")]),
  [E("Una compañera te muestra una ficha sin autor ni título. ¿Qué le falta: los datos de la fuente o la categoría?", "Los datos de la fuente", "Permiten ubicar la información.")],
  [E("En una investigación, ¿qué es una categoría de fichas?", "Un grupo en que se ordena la información", "Organiza las fichas por subtema."),
   E("En Lenguaje: ¿Qué es el plagio?", "Copiar sin indicar la fuente", "Presenta ideas ajenas como propias."),
   E("¿Qué tipo de ficha usa comillas?", "La de cita textual", "Reproduce las palabras exactas.")],
  ("Con la pregunta «¿Qué tipos de narrador existen?», clasifica estas fichas de ejemplo: 1) «El narrador cuenta lo que ve, pero no entra en la mente de los personajes». 2) «El narrador es un personaje de la historia y habla en primera persona». 3) «El narrador sabe lo que piensan todos los personajes». Escribe para cada una la categoría y escribe una paráfrasis de la ficha 2.",
   "1) Testigo. 2) Protagonista. 3) Omnisciente. Paráfrasis de 2: «Quien narra es uno de los personajes y cuenta usando la primera persona».",
   ["clasifica correctamente", "distingue cita y paráfrasis", "parafrasea con sentido"], ["tres categorías", "una paráfrasis"], ["copiar casi igual", "mezclar categorías"], "Compara con otra persona si coinciden las categorías."),
  "Haz tres fichas sobre un tema que investigues, con fuente y categoría.",
  "Escribe tres citas textuales y sus paráfrasis para un mismo tema.")

L(OA24, 6,
  MAT_I,
  "Aprenderé a comunicar los resultados de una investigación en un informe breve, nombrando las fuentes con un formato simple.",
  ["Registro información en fichas.", "Categorizo mi información."],
  ["Un informe breve de investigación tiene cuatro partes. La introducción presenta la pregunta y por qué es importante. El desarrollo expone los hallazgos ordenados por categoría. La conclusión responde la pregunta con tus propias palabras. Las referencias enumeran las fuentes usadas.",
   "Para nombrar las fuentes, usa un formato simple: Autor. Título. Año. Por ejemplo: «Guzmán, Ana. Guía del narrador. 2020». Dentro del texto puedes indicar de dónde viene una idea con una frase como «según Guzmán (2020)». Si usas una cita textual, escribe las palabras exactas entre comillas y la fuente. Si parafraseas, igualmente nombra la fuente.",
   "Un informe honesto separa lo que dicen las fuentes de lo que concluyes tú. Revisa que cada afirmación importante tenga respaldo. Al final, comprueba que todas las fuentes mencionadas estén en las referencias y que todas las referencias se hayan usado. Así, tus lectores podrán comprobar tu trabajo y confiar en él."],
  [("informe", "texto que comunica los resultados de una investigación"), ("hallazgo", "dato o idea encontrada al investigar"), ("referencias", "lista de las fuentes usadas en un informe"), ("citar", "indicar la fuente de una idea o frase")],
  [("Escribir una referencia", "Escribe la referencia de: autora Ana Guzmán, título «Guía del narrador», año 2020.",
    ["Uso el formato Autor. Título. Año.", "Escribo el apellido primero.", "Guzmán, Ana. Guía del narrador. 2020."],
    "Guzmán, Ana. Guía del narrador. 2020."),
   ("Citar en el texto", "¿Cómo indicas dentro del texto que una idea viene de esa fuente?",
    ["Uso el apellido y el año.", "Puedo escribir «según Guzmán (2020)».", "Así el lector sabe de dónde viene."],
    "Según Guzmán (2020)")],
  [("Poner fuentes en las referencias que no se usaron.", "Se quiere que parezca más serio.", "Incluye solo lo que usaste."),
   ("No citar cuando se parafrasea.", "Se piensa que las palabras propias bastan.", "La idea sigue siendo de otra persona: nombra la fuente.")],
  ([E("¿Cuál es la parte que presenta la pregunta: la introducción o la conclusión?", "La introducción", "Abre el informe."),
    E("¿Dónde se enumeran las fuentes: en las referencias o en la introducción?", "En las referencias", "Es su función."),
    E("¿Qué parte responde la pregunta con tus palabras: el desarrollo o la conclusión?", "La conclusión", "Cierra la investigación.")],
   [E("¿Cuál es el formato de la referencia según la clase: «Autor. Título. Año.» o «Año. Título. Autor.»?", "Autor. Título. Año.", "Es el formato simple de la clase."),
    E("Si parafraseas a una autora, ¿nombras la fuente?", "Sí", "La idea es de ella."),
    E("¿Qué indica «según Guzmán (2020)»: la fuente de una idea o la página?", "La fuente de una idea", "Nombra autor y año.")],
   [E("Un informe tiene introducción, desarrollo con 3 categorías, conclusión y referencias. ¿Cuántas categorías se exponen en el desarrollo?", "3", "Son las tres categorías."),
    E("Ordena: A) conclusión; B) introducción; C) desarrollo; D) referencias. ¿Cuál es el orden correcto?", "B, C, A, D", "Se presenta, se expone, se concluye y se enumeran fuentes."),
    E("Mencionas tres fuentes en el texto y enumeras cuatro en las referencias. ¿Cuántas sobran?", "1", "Una no se usó.")],
   [E("Ana escribe «Según Guzmán (2020), el narrador testigo cuenta lo que ve» y lo incluye en sus referencias. Beto escribe lo mismo pero no nombra la fuente. ¿Quién citó bien?", "Ana", "Indicó la fuente."),
    E("Un informe presenta solo hechos copiados de las fuentes, sin conclusión propia. ¿Está completo?", "No", "Falta la respuesta a la pregunta.")],
   [E("Tu introducción plantea la pregunta «¿Qué tipos de narrador existen?». ¿Qué debe hacer la conclusión con esa pregunta?", "Responderla con tus palabras", "Cierra la investigación."),
    E("¿Qué debes comprobar al final: que todas las fuentes del texto estén en las referencias y viceversa?", "Sí", "Así el informe es coherente.")]),
  [E("Terminas tu informe sobre los narradores y no incluyes referencias. ¿Qué falta: la introducción o las fuentes usadas?", "Las fuentes usadas", "Las referencias las enumeran.")],
  [E("En Lenguaje: ¿Cuántas partes tiene el informe de la clase?", "4", "Introducción, desarrollo, conclusión y referencias."),
   E("En Lenguaje: ¿Qué es citar?", "Indicar la fuente de una idea o frase", "Muestra de dónde viene."),
   E("¿Se nombra la fuente cuando se parafrasea?", "Sí", "La idea no es propia.")],
  ("Escribe un informe de seis oraciones a partir de estas fichas de ejemplo: Ficha 1 (Guzmán, Ana. Guía del narrador. 2020): «El narrador protagonista cuenta en primera persona». Ficha 2 (Pérez, Luis. Contar historias. 2018): «El narrador testigo cuenta lo que observa». Incluye introducción con la pregunta «¿Qué tipos de narrador existen?», un párrafo por categoría, una conclusión y las referencias.",
   "Introducción: ¿Qué tipos de narrador existen? Es útil para entender cómo se cuenta una historia. Según Guzmán (2020), el narrador protagonista cuenta en primera persona. Según Pérez (2018), el testigo cuenta lo que observa. Conclusión: hay al menos dos tipos que cambian desde dónde se cuenta. Referencias: Guzmán, Ana. Guía del narrador. 2020. Pérez, Luis. Contar historias. 2018.",
   ["incluye las cuatro partes", "cita con apellido y año", "referencias en el formato"], ["informe de seis oraciones"], ["no citar", "olvidar la conclusión"], "Lee el informe a otra persona y pregúntale si sabe de dónde salió cada dato."),
  "Escribe la referencia de un libro que tengas en casa con el formato de la clase.",
  "Escribe una introducción de tres oraciones para un informe sobre un tema de lenguaje.")
